sys_script.script:
(function executeRule(current, previous) {
    if (!current.car.changes() && !current.start_date.changes() && !current.end_date.changes() && !current.state.changes()) {
        return;
    }
    var st = current.getValue('state');
    if (st == 'cancelled' || st == 'closed') {
        return;
    }
    var carId = current.getValue('car');
    var start = current.getValue('start_date');
    if (!carId || !start) {
        return;
    }
    var end = current.getValue('end_date') || start;

    var other = new GlideRecord('x_2203703_car_re_0_reservation');
    other.addQuery('car', carId);
    other.addQuery('state', 'reserved');
    other.addQuery('start_date', '<=', end);
    other.addQuery('sys_id', '!=', current.getUniqueValue());
    other.orderBy('start_date');
    other.query();
    while (other.next()) {
        var otherEnd = other.getValue('end_date') || other.getValue('start_date');
        if (otherEnd >= start) {
            gs.addErrorMessage('The car "' + current.getDisplayValue('car') + '" is already reserved from ' +
                other.getDisplayValue('start_date') + ' to ' + other.getDisplayValue('end_date') +
                '. Choose another car or other dates.');
            current.setAbortAction(true);
            return;
        }
    }
})(current, previous);
